cat > sim/toml_lite.gd <<'EOF'
extends RefCounted
## Минимальный разбор TOML для data/balance.toml: [секция], ключ = число | true/false | "строка", комментарии #.
## Возвращает { секция: { ключ: значение } }.


static func parse(text: String) -> Dictionary:
	var out := {}
	var cur: Dictionary = out
	for raw in text.split("\n"):
		var line := _strip_comment(raw).strip_edges()
		if line.is_empty():
			continue
		if line.begins_with("[") and line.ends_with("]"):
			var name := line.substr(1, line.length() - 2).strip_edges()
			out[name] = {}
			cur = out[name]
			continue
		var eq := line.find("=")
		if eq < 0:
			push_error("toml_lite: строка без '=': " + line)
			continue
		cur[line.substr(0, eq).strip_edges()] = _value(line.substr(eq + 1).strip_edges())
	return out


static func load_file(path: String) -> Dictionary:
	var f := FileAccess.open(path, FileAccess.READ)
	if f == null:
		push_error("toml_lite: нет файла " + path)
		return {}
	return parse(f.get_as_text())


static func _strip_comment(s: String) -> String:
	var in_str := false
	for i in s.length():
		var c := s[i]
		if c == "\"":
			in_str = not in_str
		elif c == "#" and not in_str:
			return s.substr(0, i)
	return s


static func _value(v: String) -> Variant:
	if v == "true":
		return true
	if v == "false":
		return false
	if v.begins_with("\"") and v.ends_with("\"") and v.length() >= 2:
		return v.substr(1, v.length() - 2)
	if v.is_valid_int():
		return int(v)
	return float(v)
EOF
cat > sim/rng.gd <<'EOF'
extends RefCounted
## Единственный источник случайности симуляции (инвариант 3): xorshift64*, состояние — одно целое.

const FALLBACK_SEED := 0x1E3779B97F4A7C15
const MUL := 0x2545F4914F6CDD1D
const U32 := 0xFFFFFFFF
const U32_SPAN := 4294967296.0

var state: int = FALLBACK_SEED


func _init(seed_value: int = 1) -> void:
	reseed(seed_value)


func reseed(seed_value: int) -> void:
	state = seed_value if seed_value != 0 else FALLBACK_SEED
	next_u32()  # прогрев: близкие сиды расходятся


func next_u32() -> int:
	var x := state
	x ^= x << 13
	x ^= (x >> 7) & 0x01FFFFFFFFFFFFFF  # логический сдвиг
	x ^= x << 17
	state = x
	return ((x * MUL) >> 32) & U32


func next_float() -> float:
	return float(next_u32()) / U32_SPAN


func range_int(lo: int, hi: int) -> int:
	return lo + next_u32() % (hi - lo + 1)
EOF
cat > sim/hasher.gd <<'EOF'
extends RefCounted
## FNV-1a 64 по целым: хеш состояния симуляции (инвариант 4). Дроби квантуются до 1/QUANT.

const OFFSET := -3750763034362895579  # 0xcbf29ce484222325 как знаковое
const PRIME := 0x100000001b3
const QUANT := 10000.0
const NIBBLES := 16
const BYTE_MASK := 0xFF
const BYTES := 8

var h: int = OFFSET


func add_int(v: int) -> void:
	for i in BYTES:
		h = (h ^ ((v >> (i * 8)) & BYTE_MASK)) * PRIME


func add_float(v: float) -> void:
	add_int(roundi(v * QUANT))


func add_vec(v: Vector2) -> void:
	add_float(v.x)
	add_float(v.y)


func hex() -> String:
	var s := ""
	for i in range(NIBBLES - 1, -1, -1):
		s += "0123456789abcdef"[(h >> (i * 4)) & 0xF]
	return s
EOF

