cd "C:/visual projects/game" && cat > sim/collision.gd <<'EOF'
extends RefCounted
## Коллизии героя-круга с кругами и прямоугольниками плоскости + границы арены. Всё в 2D, без узлов.
## Коллайдеры: {"kind":"circle","x","y","r"} | {"kind":"box","x","y","hx","hy"} (центр и полуразмеры, оси мира).

const EPS := 0.000001


## Сдвиг круга радиуса r из pos на delta с выталкиванием; длинный шаг дробится на подшаги.
static func move(pos: Vector2, delta: Vector2, r: float, level: Dictionary, bal: Dictionary) -> Vector2:
	var sim: Dictionary = bal["sim"]
	var steps := maxi(1, ceili(delta.length() / (r * float(sim["collide_substep"]))))
	var part := delta / float(steps)
	var colliders: Array = level.get("colliders", [])
	for _s in steps:
		pos += part
		for _i in int(sim["collide_iterations"]):
			var moved := false
			for c in colliders:
				var push := _push_out(pos, r, c)
				if push != Vector2.ZERO:
					pos += push
					moved = true
			if not moved:
				break
		pos = _clamp_bounds(pos, r, level.get("bounds", {}))
	return pos


static func _clamp_bounds(pos: Vector2, r: float, b: Dictionary) -> Vector2:
	if b.is_empty():
		return pos
	return Vector2(clampf(pos.x, float(b["min"][0]) + r, float(b["max"][0]) - r),
			clampf(pos.y, float(b["min"][1]) + r, float(b["max"][1]) - r))


static func _push_out(pos: Vector2, r: float, c: Dictionary) -> Vector2:
	var center := Vector2(float(c["x"]), float(c["y"]))
	if c["kind"] == "circle":
		var d := pos - center
		var need := r + float(c["r"])
		var len := d.length()
		if len >= need:
			return Vector2.ZERO
		return (d / len if len > EPS else Vector2.RIGHT) * (need - len)
	var half := Vector2(float(c["hx"]), float(c["hy"]))
	var rel := pos - center
	var near := Vector2(clampf(rel.x, -half.x, half.x), clampf(rel.y, -half.y, half.y))
	var off := rel - near
	var dist := off.length()
	if dist > EPS:
		return Vector2.ZERO if dist >= r else off / dist * (r - dist)
	# центр внутри прямоугольника: выход по оси наименьшего проникновения
	var gap := half - rel.abs()
	if gap.x < gap.y:
		return Vector2(signf(rel.x) if rel.x != 0.0 else 1.0, 0.0) * (gap.x + r)
	return Vector2(0.0, signf(rel.y) if rel.y != 0.0 else 1.0) * (gap.y + r)
EOF
cat > sim/world_state.gd <<'EOF'
extends RefCounted
## Всё состояние симуляции. Вид читает отсюда, сам ничего не хранит (инвариант 2).
const Hasher := preload("res://sim/hasher.gd")
const Rng := preload("res://sim/rng.gd")

var tick: int = 0
var rng: RefCounted
var level: Dictionary = {}
var player := {
	"pos": Vector2.ZERO,
	"vel": Vector2.ZERO,
	"facing": Vector2.DOWN,
	"dash_left": 0,        # оставшиеся тики рывка (0 — не рывок)
	"dash_dir": Vector2.ZERO,
	"charges": 0,
	"recharge": 0,         # тиков до восстановления следующего заряда
	"dash_buf": 0,         # тиков, пока нажатие рывка ещё помнится
}


func _init(seed_value: int, lvl: Dictionary, bal: Dictionary) -> void:
	rng = Rng.new(seed_value)
	level = lvl
	var s: Array = lvl.get("spawn", [0.0, 0.0])
	player["pos"] = Vector2(float(s[0]), float(s[1]))
	player["charges"] = int(bal["dash"]["charges"])


func state_hash() -> String:
	var h := Hasher.new()
	h.add_int(tick)
	h.add_int(rng.state)
	h.add_vec(player["pos"])
	h.add_vec(player["vel"])
	h.add_vec(player["facing"])
	h.add_vec(player["dash_dir"])
	for k in ["dash_left", "charges", "recharge", "dash_buf"]:
		h.add_int(int(player[k]))
	return h.hex()
EOF
cat > sim/movement.gd <<'EOF'
extends RefCounted
## Бег и рывок героя на плоскости (поведение по Wizard of Legend). Один вызов = один тик.
const Collision := preload("res://sim/collision.gd")


## input: {"move": Vector2 (длина ≤ 1), "dash": bool — нажатие в этот тик}
static func step(st: RefCounted, input: Dictionary, bal: Dictionary) -> void:
	var rate := float(bal["sim"]["tick_rate"])
	var dt := 1.0 / rate
	var p: Dictionary = st.player
	var move: Vector2 = input.get("move", Vector2.ZERO)
	if move.length() > 1.0:
		move = move.normalized()
	if move.length() < float(bal["sim"]["move_deadzone"]):
		move = Vector2.ZERO

	_recharge(p, bal, rate)
	if input.get("dash", false):
		p["dash_buf"] = roundi(float(bal["dash"]["buffer"]) * rate)
	elif p["dash_buf"] > 0:
		p["dash_buf"] -= 1
	if p["dash_left"] == 0 and p["dash_buf"] > 0 and p["charges"] > 0:
		_start_dash(p, move, bal, rate)

	var delta: Vector2
	if p["dash_left"] > 0:
		var total := roundi(float(bal["dash"]["duration"]) * rate)
		var frac := (float(total - p["dash_left"]) + 0.5) / float(total)  # доля пройденного, середина тика
		var peak: float = 2.0 * float(bal["dash"]["distance"]) / float(bal["dash"]["duration"])
		p["vel"] = p["dash_dir"] * peak * (1.0 - frac)  # линейно до нуля: путь = distance
		p["dash_left"] -= 1
		if p["dash_left"] == 0:
			p["vel"] = Vector2.ZERO
		delta = p["vel"] * dt
	else:
		var speed := float(bal["player"]["run_speed"])
		var ticks := float(bal["player"]["run_accel_time"] if move != Vector2.ZERO else bal["player"]["run_decel_time"])
		p["vel"] = (p["vel"] as Vector2).move_toward(move * speed, speed / maxf(ticks * rate, 1.0))
		if move != Vector2.ZERO:
			p["facing"] = move.normalized()
		delta = p["vel"] * dt
	p["pos"] = Collision.move(p["pos"], delta, float(bal["player"]["radius"]), st.level, bal)


static func _start_dash(p: Dictionary, move: Vector2, bal: Dictionary, rate: float) -> void:
	var dir: Vector2 = move.normalized() if move != Vector2.ZERO else p["facing"]
	p["dash_dir"] = dir
	p["facing"] = dir
	p["dash_left"] = roundi(float(bal["dash"]["duration"]) * rate)
	p["dash_buf"] = 0
	if p["charges"] == int(bal["dash"]["charges"]):
		p["recharge"] = roundi(float(bal["dash"]["cooldown"]) * rate)
	p["charges"] -= 1


static func _recharge(p: Dictionary, bal: Dictionary, rate: float) -> void:
	if p["charges"] >= int(bal["dash"]["charges"]):
		return
	p["recharge"] -= 1
	if p["recharge"] <= 0:
		p["charges"] += 1
		p["recharge"] = roundi(float(bal["dash"]["cooldown"]) * rate) if p["charges"] < int(bal["dash"]["charges"]) else 0
EOF
cat > sim/sim.gd <<'EOF'
extends RefCounted
## Вход в симуляцию: создать мир, шагнуть тик, прогнать реплей. Данные грузятся из data/ (инвариант 6).
const TomlLite := preload("res://sim/toml_lite.gd")
const WorldState := preload("res://sim/world_state.gd")
const Movement := preload("res://sim/movement.gd")

const BALANCE_PATH := "res://data/balance.toml"

var bal: Dictionary
var state: RefCounted


static func load_json(path: String) -> Dictionary:
	var f := FileAccess.open(path, FileAccess.READ)
	if f == null:
		push_error("sim: нет файла " + path)
		return {}
	var parsed: Variant = JSON.parse_string(f.get_as_text())
	return parsed if parsed is Dictionary else {}


func _init(seed_value: int, level_path: String, balance: Dictionary = {}) -> void:
	bal = balance if not balance.is_empty() else TomlLite.load_file(BALANCE_PATH)
	state = WorldState.new(seed_value, load_json(level_path), bal)


func step(input: Dictionary) -> void:
	Movement.step(state, input, bal)
	state.tick += 1


## Реплей: {"seed", "level", "ticks", "inputs":[{"t", "mx"?, "my"?, "dash"?}]}.
## mx/my держатся до следующей записи; dash — импульс одного тика t.
static func run_replay(rep: Dictionary) -> RefCounted:
	var s := new(int(rep["seed"]), str(rep["level"]))
	var inputs: Array = rep["inputs"]
	var i := 0
	var move := Vector2.ZERO
	for t in int(rep["ticks"]):
		var dash := false
		while i < inputs.size() and int(inputs[i]["t"]) == t:
			var e: Dictionary = inputs[i]
			if e.has("mx") or e.has("my"):
				move = Vector2(float(e.get("mx", move.x)), float(e.get("my", move.y)))
			dash = dash or bool(e.get("dash", false))
			i += 1
		s.step({"move": move, "dash": dash})
	return s
EOF
cat > tools/headless_run.gd <<'EOF'
extends SceneTree
## Прогон реплея без окна:
##   godot --headless --path . --script tools/headless_run.gd -- --replay tests/replays/<имя>.replay.json
## Печатает "HASH <hex> TICKS <n> POS x y" — сверяет tools/replay_test.py.
const Sim := preload("res://sim/sim.gd")


func _initialize() -> void:
	var a := OS.get_cmdline_user_args()
	var idx := a.find("--replay")
	if idx < 0 or idx + 1 >= a.size():
		printerr("headless_run: нужен --replay <файл>")
		quit(2)
		return
	var rep := Sim.load_json("res://" + a[idx + 1].trim_prefix("res://"))
	if rep.is_empty():
		quit(2)
		return
	var s := Sim.run_replay(rep)
	var p: Vector2 = s.state.player["pos"]
	print("HASH %s TICKS %d POS %.3f %.3f" % [s.state.state_hash(), s.state.tick, p.x, p.y])
	quit(0)
EOF

