extends SceneTree
## Прогон реплея без окна:
##   godot --headless --path . --script tools/headless_run.gd -- --replay tests/replays/<имя>.replay.json
## Печатает "HASH <hex> TICKS <n> POS x y" — сверяет tools/replay_test.py.
const Sim := preload("res://sim/sim.gd")


func _initialize() -> void:
	var a := OS.get_cmdline_user_args()
	var idx := a.find("--replay")
	if idx < 0 or idx + 1 >= a.size():
		printerr("headless_run: нужен --replay <файл>")
		quit(2)
		return
	var rep := Sim.load_json("res://" + a[idx + 1].trim_prefix("res://"))
	if rep.is_empty():
		quit(2)
		return
	var s := Sim.run_replay(rep)
	var p: Vector2 = s.state.player["pos"]
	print("HASH %s TICKS %d POS %.3f %.3f" % [s.state.state_hash(), s.state.tick, p.x, p.y])
	quit(0)
