	p["dash_left"] = roundi(float(bal["dash"]["duration"]) * rate)
	p["dash_buf"] = 0
	if p["charges"] == int(bal["dash"]["charges"]):
		p["recharge"] = roundi(float(bal["dash"]["cooldown"]) * rate)
	p["charges"] -= 1


static func _recharge(p: Dictionary, bal: Dictionary, rate: float) -> void:
	if p["charges"] >= int(bal["dash"]["charges"]):
		return
	p["recharge"] -= 1
	if p["recharge"] <= 0:
		p["charges"] += 1
		p["recharge"] = roundi(float(bal["dash"]["cooldown"]) * rate) if p["charges"] < int(bal["dash"]["charges"]) else 0

extends RefCounted
## Вход в симуляцию: создать мир, шагнуть тик, прогнать реплей. Данные грузятся из data/ (инвариант 6).
const TomlLite := preload("res://sim/toml_lite.gd")
const WorldState := preload("res://sim/world_state.gd")
const Movement := preload("res://sim/movement.gd")

const BALANCE_PATH := "res://data/balance.toml"

var bal: Dictionary
var state: RefCounted


static func load_json(path: String) -> Dictionary:
	var f := FileAccess.open(path, FileAccess.READ)
	if f == null:
		push_error("sim: нет файла " + path)
		return {}
	var parsed: Variant = JSON.parse_string(f.get_as_text())
	return parsed if parsed is Dictionary else {}


func _init(seed_value: int, level_path: String, balance: Dictionary = {}) -> void:
	bal = balance if not balance.is_empty() else TomlLite.load_file(BALANCE_PATH)
	state = WorldState.new(seed_value, load_json(level_path), bal)


func step(input: Dictionary) -> void:
	Movement.step(state, input, bal)
	state.tick += 1


## Реплей: {"seed", "level", "ticks", "inputs":[{"t", "mx"?, "my"?, "dash"?}]}.
## mx/my держатся до следующей записи; dash — импульс одного тика t.
static func run_replay(rep: Dictionary) -> RefCounted:
	var s := new(int(rep["seed"]), str(rep["level"]))
	var inputs: Array = rep["inputs"]
	var i := 0
	var move := Vector2.ZERO
	for t in int(rep["ticks"]):
		var dash := false
		while i < inputs.size() and int(inputs[i]["t"]) == t:
			var e: Dictionary = inputs[i]
			if e.has("mx") or e.has("my"):
				move = Vector2(float(e.get("mx", move.x)), float(e.get("my", move.y)))
			dash = dash or bool(e.get("dash", false))
			i += 1
		s.step({"move": move, "dash": dash})
	return s

extends SceneTree
## Прогон реплея без окна:
##   godot --headless --path . --script tools/headless_run.gd -- --replay tests/replays/<имя>.replay.json
## Печатает "HASH <hex> TICKS <n> POS x y" — сверяет tools/replay_test.py.
const Sim := preload("res://sim/sim.gd")


func _initialize() -> void:
	var a := OS.get_cmdline_user_args()
	var idx := a.find("--replay")
	if idx < 0 or idx + 1 >= a.size():
		printerr("headless_run: нужен --replay <файл>")
		quit(2)
		return
	var rep := Sim.load_json("res://" + a[idx + 1].trim_prefix("res://"))
	if rep.is_empty():
		quit(2)
		return
	var s := Sim.run_replay(rep)
	var p: Vector2 = s.state.player["pos"]
	print("HASH %s TICKS %d POS %.3f %.3f" % [s.state.state_hash(), s.state.tick, p.x, p.y])
	quit(0)

