extends GutTest
## Бег, рывок, коллизии и детерминизм симуляции (sim/). Числа берутся из data/balance.toml.

const Sim := preload("res://sim/sim.gd")
const Rng := preload("res://sim/rng.gd")
const TomlLite := preload("res://sim/toml_lite.gd")
const LEVEL := "res://data/levels/cape.json"
const EMPTY_LEVEL := "res://tests/fixtures/empty_level.json"


func _sim(level := EMPTY_LEVEL) -> RefCounted:
	return Sim.new(1, level)


func _ticks(s: RefCounted, n: int, move: Vector2, dash_first := false) -> void:
	for i in n:
		s.step({"move": move, "dash": dash_first and i == 0})


func _rate(s: RefCounted) -> int:
	return int(s.bal["sim"]["tick_rate"])


func _dash_ticks(s: RefCounted) -> int:
	return roundi(float(s.bal["dash"]["duration"]) * _rate(s))


func test_balance_parsed() -> void:
	var b := TomlLite.load_file("res://data/balance.toml")
	assert_eq(b["dash"]["charges"], 2)
	assert_gt(float(b["player"]["run_speed"]), 0.0)


func test_run_reaches_speed_in_8_directions() -> void:
	for d in [Vector2.RIGHT, Vector2.LEFT, Vector2.UP, Vector2.DOWN, Vector2(1, 1), Vector2(-1, 1), Vector2(1, -1), Vector2(-1, -1)]:
		var s := _sim()
		_ticks(s, _rate(s), d)  # диагонали не нормированы на входе: сим обязан обрезать до 1
		assert_almost_eq((s.state.player["vel"] as Vector2).length(), float(s.bal["player"]["run_speed"]), 0.01, "dir %s" % d)


func test_dash_distance_matches_balance() -> void:
	var s := _sim()
	_ticks(s, _dash_ticks(s), Vector2.RIGHT, true)
	assert_almost_eq((s.state.player["pos"] as Vector2).x, float(s.bal["dash"]["distance"]), 0.35)


func test_dash_uses_charges_and_recharges() -> void:
	var s := _sim()
	for i in int(s.bal["dash"]["charges"]):
		_ticks(s, _dash_ticks(s) + 1, Vector2.RIGHT, true)
	assert_eq(s.state.player["charges"], 0, "заряды потрачены")
	_ticks(s, 1, Vector2.RIGHT, true)
	assert_eq(s.state.player["dash_left"], 0, "без заряда рывка нет")
	_ticks(s, roundi(float(s.bal["dash"]["cooldown"]) * _rate(s)), Vector2.ZERO)
	assert_gte(s.state.player["charges"], 1, "заряд вернулся за cooldown")


func test_dash_without_input_goes_along_facing() -> void:
	var s := _sim()
	_ticks(s, 10, Vector2.LEFT)
	var x0: float = s.state.player["pos"].x
	_ticks(s, _dash_ticks(s), Vector2.ZERO, true)
	assert_lt(s.state.player["pos"].x, x0 - 4.0)


func test_stops_at_house_and_cannot_dash_through() -> void:
	var s := _sim(LEVEL)
	var house: Dictionary = {}
	for c in s.state.level["colliders"]:
		if c["id"] == "keeper_house":
			house = c
	var wall_x := float(house["x"]) - float(house["hx"])
	s.state.player["pos"] = Vector2(wall_x - 3.0, float(house["y"]))
	for i in 4:
		_ticks(s, 30, Vector2.RIGHT, true)
	assert_lte(s.state.player["pos"].x, wall_x - float(s.bal["player"]["radius"]) + 0.001, "упёрся в стену дома")


func test_bounds_hold() -> void:
	var s := _sim(LEVEL)
	_ticks(s, 600, Vector2.DOWN, true)
	var b: Dictionary = s.state.level["bounds"]
	assert_lte(s.state.player["pos"].y, float(b["max"][1]))


func test_replay_deterministic() -> void:
	var rep := Sim.load_json("res://tests/replays/run_dash.replay.json")
	assert_eq(Sim.run_replay(rep).state.state_hash(), Sim.run_replay(rep).state.state_hash())


func test_rng_deterministic_and_seeded() -> void:
	var a := Rng.new(7)
	var b := Rng.new(7)
	var c := Rng.new(8)
	var same := true
	var differs := false
	for i in 50:
		var x := a.next_u32()
		same = same and x == b.next_u32()
		differs = differs or x != c.next_u32()
	assert_true(same)
	assert_true(differs)
	assert_between(a.next_float(), 0.0, 1.0)

"""Схемы и ссылочная целостность data/ и tests/replays/ (инвариант 7)."""
import json
import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
errs = []


def err(path, msg):
    errs.append(f"{path.relative_to(ROOT).as_posix()}: {msg}")


def load(path):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception as e:  # noqa: BLE001
        err(path, f"не JSON: {e}")


def check_balance():
    p = ROOT / "data" / "balance.toml"
    try:
        b = tomllib.loads(p.read_text(encoding="utf-8"))
    except Exception as e:  # noqa: BLE001
        return err(p, f"не TOML: {e}")
    need = {"sim": ["tick_rate", "move_deadzone", "collide_substep", "collide_iterations"],
            "player": ["radius", "run_speed", "run_accel_time", "run_decel_time"],
            "dash": ["distance", "duration", "cooldown", "charges", "buffer"]}
    for sec, keys in need.items():
        for k in keys:
            v = b.get(sec, {}).get(k)
            if not isinstance(v, (int, float)) or v <= 0:
                err(p, f"[{sec}] {k}: нужно положительное число, есть {v!r}")


def check_level(p):
    d = load(p)
    if not isinstance(d, dict):
        return
    models = {m.stem for m in (ROOT / "assets" / "models").glob("*.glb")}
    for k in ("id", "spawn", "bounds", "props", "colliders"):
        if k not in d:
            err(p, f"нет ключа {k}")
    for pr in d.get("props", []):
        if pr.get("model") not in models:
            err(p, f"prop {pr.get('id')}: нет модели {pr.get('model')!r} в assets/models")
        for k in ("id", "x", "y"):
            if k not in pr:
                err(p, f"prop {pr.get('id')}: нет {k}")
    ids = set()
    for c in d.get("colliders", []):
        need = ("x", "y", "r") if c.get("kind") == "circle" else ("x", "y", "hx", "hy") if c.get("kind") == "box" else None
        if need is None:
            err(p, f"collider {c.get('id')}: kind должен быть circle|box")
        elif any(k not in c for k in need):
            err(p, f"collider {c.get('id')}: нужны поля {need}")
        if c.get("id") in ids:
            err(p, f"collider: дубль id {c.get('id')}")
        ids.add(c.get("id"))
    b = d.get("bounds")
    if b and not (b["min"][0] < b["max"][0] and b["min"][1] < b["max"][1]):
        err(p, "bounds: min должен быть меньше max")


def check_replay(p):
    d = load(p)
    if not isinstance(d, dict):
        return
    for k in ("seed", "level", "ticks", "inputs", "expect_hash"):
        if k not in d:
            err(p, f"нет ключа {k}")
    lv = d.get("level", "")
    if not (ROOT / lv.removeprefix("res://")).exists():
        err(p, f"нет уровня {lv}")
    last = -1
    for e in d.get("inputs", []):
        if e.get("t", -1) < last:
            err(p, "inputs не отсортированы по t")
        last = e.get("t", -1)
    if d.get("inputs") and last >= d.get("ticks", 0):
        err(p, "ввод после конца реплея")


def main():
    check_balance()
    for p in sorted((ROOT / "data").rglob("*.json")):
        (check_level if p.parent.name == "levels" else load)(p)
    for p in sorted((ROOT / "tests" / "replays").glob("*.replay.json")):
        check_replay(p)
    for e in errs:
        print("FAIL", e)
    print("validate_content:", "FAIL" if errs else "ok")
    return 1 if errs else 0


if __name__ == "__main__":
    sys.exit(main())
